#!/usr/bin/env python3import sysfrom google import genai# Get the question from command line argumentsif len(sys.argv) < 2:    print("Usage: python ask_chatgpt.py \"Your question here\"")    sys.exit(1)question = " ".join(sys.argv[1:])# Call Geminiclient = genai.Client()response = client.models.generate_content(    model="gemini-3-flash-preview",    contents=question,)print(response.text)